javascript:
frappe.query_reports["Monthly Sales Abstract Report"] = {
    filters: [
        {
            fieldname: "from_date",
            label: __("From Date"),
            fieldtype: "Date",
            default: frappe.datetime.month_start(),
            reqd: 1
        },
        {
            fieldname: "to_date",
            label: __("To Date"),
            fieldtype: "Date",
            default: frappe.datetime.month_end(),
            reqd: 1
        },
        {
            fieldname: "company",
            label: __("Company"),
            fieldtype: "Link",
            options: "Company",
            default: frappe.defaults.get_user_default("Company"),
            reqd: 0,
            on_change: function() {
                frappe.query_report.refresh();
            }
        }
    ],

    // Format bold rows for section headers and totals
    formatter: function(value, row, column, data, default_formatter) {
        value = default_formatter(value, row, column, data);
        if (data && (
            data["Customer Name"] === "Inter state sales" ||
            data["Customer Name"] === "Within state sales" ||
            data["Customer Name"] === "Product wise Total" ||
            data["Customer Name"] === "TOTAL"
        )) {
            value = "<strong>" + value + "</strong>";
        }
        return value;
    }
};

